const item = $input.first().json;
const q = item.query || {};
const mode = String(q['hub.mode'] || q.hub_mode || '');
const token = String(q['hub.verify_token'] || q.hub_verify_token || '');
const challenge = String(q['hub.challenge'] || q.hub_challenge || '');
const expected = String($env.XVOND_META_MESSAGING_VERIFY_TOKEN || '');
const verified = Boolean(expected && mode === 'subscribe' && token === expected && challenge);
return [{json:{verified, challenge: verified ? challenge : 'verification_failed'}}];

const crypto = require('crypto');
const item = $input.first();
const json = item.json || {};
const headers = json.headers || {};
const body = json.body || {};
const rawBase64 = item.binary?.data?.data || '';
const rawBody = rawBase64 ? Buffer.from(rawBase64, 'base64') : null;
const signatureHeader = String(headers['x-hub-signature-256'] || headers['X-Hub-Signature-256'] || '');
let registry = {};
try { registry = JSON.parse($env.XVOND_META_MESSAGING_ROUTES_JSON || '{}'); }
catch (_e) { return [{json:{success:false,_dispatch:'reject',code:'registry_invalid'}}]; }

const entries = Array.isArray(body.entry) ? body.entry : [];
if (!entries.length) return [{json:{success:true,_dispatch:'ignore',ignored:true}}];

const firstSenderId = String(entries[0]?.id || '');
const routeEntry = Object.entries(registry).find(([, route]) => String(route?.sender_id || '') === firstSenderId);
if (!routeEntry) return [{json:{success:false,_dispatch:'reject',code:'route_not_found'}}];
const [routeKey, route] = routeEntry;

const appSecret = String(route.app_secret || '');
if (!rawBody || !appSecret || !signatureHeader.startsWith('sha256=')) {
  return [{json:{success:false,_dispatch:'reject',code:'signature_missing'}}];
}
const expected = 'sha256=' + crypto.createHmac('sha256', appSecret).update(rawBody).digest('hex');
const a = Buffer.from(expected);
const b = Buffer.from(signatureHeader);
if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) {
  return [{json:{success:false,_dispatch:'reject',code:'signature_invalid'}}];
}

const output = [];
for (const entry of entries) {
  const senderAccountId = String(entry?.id || '');
  const match = Object.entries(registry).find(([, candidate]) =>
    String(candidate?.sender_id || '') === senderAccountId
  );
  if (!match) continue;
  const [matchedRouteKey, matchedRoute] = match;
  const expectedChannel = String(matchedRoute.channel_type || '').trim().toLowerCase();
  if (!['instagram','messenger'].includes(expectedChannel)) continue;

  const events = Array.isArray(entry?.messaging) ? entry.messaging : [];
  for (const event of events) {
    const message = event?.message || null;
    const text = String(message?.text || '').trim();
    const senderId = String(event?.sender?.id || '');
    const mid = String(message?.mid || '');
    if (!message || message.is_echo === true || !text || !senderId || !mid) continue;

    output.push({json:{
      success:true,
      _dispatch:'xvond',
      route_key:matchedRouteKey,
      payload:{
        company_id:Number(matchedRoute.company_id || 0),
        agent_id:Number(matchedRoute.agent_id || 0),
        channel_id:Number(matchedRoute.channel_id || 0),
        channel_type:expectedChannel,
        external_contact_id:senderId,
        external_message_id:mid,
        message:text
      }
    }});
  }
}
return output.length ? output : [{json:{success:true,_dispatch:'ignore',ignored:true}}];

async function xvondManagedRoute(companyId, connectionKey) {
  const base = String($env.XVOND_WORKFLOW_REGISTRY_URL || '').replace(/\/$/, '');
  const secret = String($env.XVOND_WORKFLOW_REGISTRY_SECRET || '');
  if (!base || !secret || !companyId || !connectionKey) return null;
  try {
    const response = await fetch(
      base + '/v1/routes/' + encodeURIComponent(String(companyId)) + '/' + encodeURIComponent(String(connectionKey)),
      {headers:{'X-Xvond-Registry-Secret':secret}}
    );
    if (!response.ok) return null;
    const payload = await response.json().catch(() => null);
    const row = payload?.route;
    if (!row) return null;
    return {
      ...(row.provider_config || {}),
      provider_secret:String(row.provider_secret || ''),
      provider_type:String(row.provider_type || ''),
      provider_url:String(row.provider_url || ''),
      company_id:Number(row.company_id || 0),
      agent_id:Number(row.agent_id || 0),
      channel_id:Number(row.channel_id || 0),
      connection_key:String(row.connection_key || connectionKey)
    };
  } catch (_error) {
    return null;
  }
}
const item = $input.first().json;
const headers = item.headers || {};
const body = item.body || item;
const supplied = String(headers['x-xvond-channel-secret'] || headers['X-Xvond-Channel-Secret'] || '');
const requestId = String(body.request_id || headers['x-xvond-request-id'] || '').trim();
const action = String(body.action || '').trim();
const data = body.data && typeof body.data === 'object' ? body.data : {};
const companyId = Number(body.company_id || 0);
const connectionKey = String(data.connection_key || '').trim();

const routeKey = `${companyId}:${connectionKey}`;
const route = await xvondManagedRoute(companyId, connectionKey);
if (!route || !route.access_token || !route.provider_secret || !route.sender_id) {
  return [{json:{success:false,_dispatch:'reject',request_id:requestId,action,error:'Meta messaging route is not configured',error_code:'provider_not_configured',data:null}}];
}
if (!supplied || supplied !== String(route.provider_secret)) {
  return [{json:{success:false,_dispatch:'reject',request_id:requestId,action,error:'Unauthorized Meta provider request',error_code:'unauthorized',data:null}}];
}
const channelType = String(route.channel_type || '').trim().toLowerCase();
if (!['instagram','messenger'].includes(channelType) || action !== 'channel.send') {
  return [{json:{success:false,_dispatch:'reject',request_id:requestId,action,error:'Unsupported Meta messaging provider action',error_code:'unsupported_action',data:null}}];
}
const recipientId = String(data.external_contact_id || '').trim();
const message = String(data.message || '').trim();
if (!requestId || !recipientId || !message) {
  return [{json:{success:false,_dispatch:'reject',request_id:requestId,action,error:'Invalid Meta send contract',error_code:'invalid_contract',data:null}}];
}
return [{json:{
  success:true,
  _dispatch:'meta_send',
  request_id:requestId,
  action,
  route_key:routeKey,
  channel_type:channelType,
  recipient_id:recipientId,
  message,
  idempotency_key:String(data.idempotency_key || '').trim()
}}];

const response = $input.first().json;
const request = $('Validate Meta Send').first().json;
const providerMessageId = String(response?.message_id || '');
if (!providerMessageId) {
  return [{json:{success:false,request_id:request.request_id,action:request.action,error:'Meta provider did not confirm the message',error_code:'provider_rejected',data:null}}];
}
return [{json:{
  success:true,
  request_id:request.request_id,
  action:request.action,
  data:{provider_message_id:providerMessageId},
  error:null
}}];
